svg.script:
(() => {
  const SVG_NS = "http://www.w3.org/2000/svg";
  const CX = 64;
  const CY = 60;
  const SCREEN_RADIUS = 52;
  const NUCLEAR_CHARGE = 5;
  const makeRng = (seed) => { let state = seed >>> 0; return () => ((state = (Math.imul(1664525, state) + 1013904223) >>> 0) / 4294967296); };
  let fallbackEntropy = (Date.now() ^ 0x41584f58) >>> 0;
  const randomSeed = () => {
    if (globalThis.crypto && globalThis.crypto.getRandomValues) {
      const value = new Uint32Array(1); globalThis.crypto.getRandomValues(value); return value[0];
    }
    fallbackEntropy = (Math.imul(1664525, fallbackEntropy) + 1013904223) >>> 0;
    return fallbackEntropy;
  };
  const gammaInteger = (random, shape, scale) => { let sum = 0; for (let i = 0; i < shape; i += 1) sum -= Math.log(Math.max(random(), Number.MIN_VALUE)); return scale * sum; };
  const isotropicDirection = (random) => { const z = 2 * random() - 1; const phi = 2 * Math.PI * random(); const rho = Math.sqrt(Math.max(0, 1 - z * z)); return { x: rho * Math.cos(phi), y: rho * Math.sin(phi), z }; };
  const orbitalDirection = (random, kind) => { for (;;) { const n = isotropicDirection(random); if (kind === "s") return n; if (kind === "p" && random() <= n.x * n.x) return n; if (kind === "d" && random() <= 4 * n.x * n.x * n.y * n.y) return n; } };
  // All three states are node-free (n = l + 1), so the hydrogen-like radial
  // density r^2|R_nl|^2 is exactly Gamma(2l + 3, n*a0 / 2Z) in Bohr units:
  // 1s -> (3, 1/2Z), 2p -> (5, 1/Z), 3d -> (7, 3/2Z), here at Z = 5.
  // Each cloud is normalised to rDisplay on the way to pixels, so Z sets
  // the physics on paper and not one pixel of the drawing.
  const orbitals = [
    { target: "samples-s", kind: "s", count: 1700, shape: 3, scale: 0.10, rDisplay: 1.030 },
    { target: "samples-p", kind: "p", count: 2600, shape: 5, scale: 0.20, rDisplay: 2.670 },
    { target: "samples-d", kind: "d", count: 3600, shape: 7, scale: 0.30, rDisplay: 4.860 }
  ];
  const appendCloudPaths = (target, commands) => {
    const glow = document.createElementNS(SVG_NS, "path"); glow.setAttribute("class", "cloud-glow"); glow.setAttribute("d", commands);
    const crisp = document.createElementNS(SVG_NS, "path"); crisp.setAttribute("class", "cloud-sample"); crisp.setAttribute("d", commands);
    target.textContent = ""; target.appendChild(glow); target.appendChild(crisp);
  };
  const renderOrbital = (orbital) => {
    const seed = randomSeed(); const random = makeRng(seed); const points = [];
    while (points.length < orbital.count) {
      const r = gammaInteger(random, orbital.shape, orbital.scale); if (r > orbital.rDisplay) continue;
      const n = orbitalDirection(random, orbital.kind); points.push({ x: r * n.x, y: r * n.y, z: r * n.z });
    }
    points.sort((a, b) => a.z - b.z);
    const pxPerU = SCREEN_RADIUS / orbital.rDisplay;
    const commands = points.map((p) => `M${(CX + p.x * pxPerU).toFixed(2)} ${(CY + p.y * pxPerU).toFixed(2)}h0`).join(" ");
    const target = document.getElementById(orbital.target);
    target.setAttribute("data-seed", `0x${seed.toString(16).padStart(8, "0")}`);
    target.setAttribute("data-z", NUCLEAR_CHARGE);
    target.setAttribute("data-radial-law", `Gamma(${orbital.shape},${orbital.scale})`);
    target.setAttribute("data-r-display", orbital.rDisplay);
    appendCloudPaths(target, commands);
  };
  const reroll = () => orbitals.forEach(renderOrbital); reroll(); setInterval(reroll, 12000);
})();
